bg=9
out=[[bg]*13 for _ in range(13)]
# 2x2 tile positions at local origins (1,1), (1,7), (7,1), (7,7)
tiles={
    (1,1):(8, [[1,0,1],[1,0,0],[0,1,0]]), # complement of source color 8 mask 010/011/101
    (1,7):(3, [[1,0,1],[1,0,1],[0,0,0]]), # complement of source color 3 mask 010/010/111
    (7,1):(1, [[1,0,1],[0,0,0],[0,1,0]]), # complement of source color 1 mask 010/111/101
    (7,7):(7, [[0,1,1],[1,0,0],[1,0,0]]), # complement of source color 7 mask 100/011/011
}
for (r,c),(color,inside) in tiles.items():
    for i in range(5):
        for j in range(5):
            out[r+i][c+j]=color if i in (0,4) or j in (0,4) else (color if inside[i-1][j-1] else bg)
print('\n'.join(' '.join(map(str,row)) for row in out))
print([len(row) for row in out])
